		"--output-format", "stream-json",
		"--print-timeout", h.Timeout,
		"--project", projectArg,
		"--dangerously-skip-permissions",
	)

	cmd.Env = append(os.Environ(), "REPO_MEMORY_HOUSEKEEPING=1")
	cmd.Dir = workDir

